def transform(grid):
    h,w=len(grid),len(grid[0])
    row_lines=[]
    for r,row in enumerate(grid):
        counts={}
        for v in row:
            if v: counts[v]=counts.get(v,0)+1
        if counts and max(counts.values())>=.7*w: row_lines.append(r)
    col_lines=[]
    for c in range(w):
        counts={}
        for r in range(h):
            v=grid[r][c]
            if v: counts[v]=counts.get(v,0)+1
        if counts and max(counts.values())>=.7*h: col_lines.append(c)
    def sampled_axis(size, lines):
        out=[]; pos=0
        for line in lines:
            if pos<line: out.append(pos)
            out.append(line); pos=line+1
        if pos<size: out.append(pos)
        return out
    rows=sampled_axis(h,row_lines); cols=sampled_axis(w,col_lines)
    return [[grid[r][c] for c in cols] for r in rows]

